<template>
<div class="task-manager" class="{{'dark-theme': isDarkMode, 'compact-mode': isCompactMode}}">
  <header class="app-header">
    <div class="logo-area">
      <span class="logo">✅</span>
      <h1 class="title">智能任务管家</h1>
