  gap: 12px;
}

.task-item {
  background: #f8fafc;
  border-radius: 10px;
  padding: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: all 0.2s;
  cursor: grab;
}

.dark-theme .task-item {
  background: #1e293b;
}

