ity: 0;\r\n  }\r\n  to {\r\n    transform: translateX(0);\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n/* 响应式 */\r\n@media (max-width: 768px) {\r\n  .main-workspace {\r\n    grid-template-columns: 1fr;\r\n  }\r\n  \r\n  .stats-section {\r\n    grid-template-columns: repeat(2, 1fr);\r\n  }\r\n  \r\n  .panel-header {\r\n    flex-direction: column;\r\n  }\r\n  \r\n  .task-controls {\r\n    width: 100%;\r\n    flex-direction: column;\r\n  }\r\n  \r\n  .search-box input {\r\n    width: 100%;\r\n  }\r\n}\r\n",
